insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 1, 'Arrive and settle', 'Sydney East', '50 min', '/photos/banner1.jpg', 'Cronulla Beach and the Kurnell headland', null, '抵埗．安頓', '悉尼東區', '50 分鐘', null);
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 2, 'Harbour day', 'Sydney East', 'No driving today', '/photos/banner2.jpg', 'Sydney Opera House and the Harbour Bridge', 'Leave the car at the hotel. Ferries and walking only — parking in the city is $60–80 a day.', '海港一日', '悉尼東區', '今日唔駕車', '架車擺喺酒店。今日只搭渡輪同步行 — 市中心泊車每日 $60–80，路又難行。');
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, 'Blue Mountains — day return', 'Sydney East', '3 hr 30 return', '/photos/banner3.jpg', 'The Three Sisters above the Jamison Valley', 'School holidays start tomorrow and fill the mountains. Today is the last quiet day up there.', '藍山 一日來回', '悉尼東區', '來回 3.5 小時', '聽日開始學校假期，藍山會逼爆。今日係最後一日仲算清靜。');
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 4, 'Coast and campus', 'Sydney East', '30 min', '/photos/banner4.jpg', 'Bondi to Bronte clifftop walk', null, '海岸．校園', '悉尼東區', '30 分鐘', null);
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 5, 'Grand Pacific Drive → Jervis Bay', 'Huskisson · 2 nights', '3 hr with stops', '/photos/banner5.jpg', 'Sea Cliff Bridge', 'Pack light for two nights. Leave the big cases at the Sydney apartment and take an overnight bag.', '大太平洋公路 → 傑維斯灣', '哈斯基森 · 住 2 晚', '連停站約 3 小時', '如果酒店肯代存，大喼留低，只帶兩日用嘅細袋。搬嘢輕鬆好多。');
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 6, 'Jervis Bay', 'Huskisson', '1 hr locally', '/photos/banner6.jpg', 'Hyams Beach, Jervis Bay', null, '傑維斯灣', '哈斯基森', '區內約 1 小時', null);
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 7, 'Back the scenic way', 'Sydney East', '3 hr with stops', '/photos/banner7.jpg', 'Fitzroy Falls', null, '山路 回程', '悉尼東區', '連停站約 3 小時', null);
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 8, 'Free day and family dinner', 'Sydney East', 'Optional', '/photos/banner8.jpg', 'Watsons Bay and The Gap', 'Deliberately unplanned. Pick one or two options, not all four.', '自由日．家庭晚餐', '悉尼東區', '視乎行程', '到今日大家已經知道仲想去邊、仲有邊個親戚未食飯。喺下面揀一至兩樣就夠，唔好四樣都做。');
insert into trip_days (trip_id, day, theme, stay, drive, banner_url, caption, rule, theme_zh, stay_zh, drive_zh, rule_zh) values ('e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 9, 'Departure · flight 14:05', '—', '40 min', '/photos/banner9.jpg', 'Sydney Fish Market, Blackwattle Bay', 'A 14:05 departure means terminal by 11:05 and car returned by 10:30. Pack everything the night before.', '回程．航班 14:05', '—', '40 分鐘', '14:05 起飛，即係 11:05 要到機場、10:30 前還車。租車訂到 14:30，早四個鐘還冇問題，但唔好照 14:30 嚟計劃朝早。今晚一定要執好晒行李。');
