insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('413cbc19-8df4-58ff-a05a-bc7e8da134b4', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 1, '06:10', '07:30', 'Sydney Airport — land', '1deebed0-4a02-527e-8289-ac2341eadc09', '✈️', 'transport', 'completed', 'booked', '6a98eedd-00db-5350-8a2e-2f20b90af3ef', null, null, null, 'Sydney Airport, Mascot NSW 2020', 'Allow a full hour for immigration, baggage and biosecurity. Australia is strict on food — declare anything you are unsure about.', null, '/photos/d1_0.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '悉尼機場 抵達', '入境、行李同檢疫要預足一個鐘。澳洲對食物好嚴格，唔肯定嘅嘢一律申報。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('68abb2c9-5902-578a-b907-38ee95d3a23c', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 1, '07:30', '08:05', 'Collect the car', '5a64c30d-acca-5185-81e7-8f1453020827', '🚗', 'transport', 'completed', 'booked', '53be79dc-7adc-5dcd-aa24-feb7343e5027', null, 62000, null, 'Car rental returns, Ross Smith Ave, Mascot NSW 2020', 'The booking says 06:00. Give the rental company your flight number so they hold the car and do not mark it a no-show. Take the e-tag for tolls.', 'Ask at the counter: Confirm the car takes four adults plus all luggage, and that the e-tag is activated.', '/photos/d1_1.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '取車', '租車訂單寫 06:00。記得畀航班編號租車公司，佢哋會留起架車，唔會當你甩底。記住攞埋 e-tag 過路費咭。', '櫃檯要問清楚：確認架車坐到四位成人加齊行李，同埋 e-tag 已經啟用。');
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('138ca0a0-4798-582b-bab0-84f9a7ff606f', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 1, '08:30', '09:25', 'Cape Solander whale lookout', '29831b36-e13d-5c17-96bd-a196c194e736', '🐋', 'activity', 'completed', 'none', null, null, null, 25, 'Cape Solander Dr, Kurnell NSW 2231', 'Free, covered platform, park at the door. Late September is peak southbound humpback season — mothers and calves travel close to shore. No walking required.', null, '/photos/d1_3.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '索蘭德角 觀鯨台', '免費，有蓋觀景台，泊車就喺門口。9月底係座頭鯨南遷高峰，母鯨帶住鯨仔會貼近海岸游。完全唔使行路。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('bd1d0bec-2f69-56c0-bd24-caeb61f4009c', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 1, '09:45', '13:25', 'Cronulla Beach — breakfast', 'd17eefe8-9502-5abc-82ec-13c4be14c579', '🏖️', 'food', 'completed', 'none', null, null, 6800, 20, 'Cronulla Beach, Kingsway, Cronulla NSW 2230', 'CronullaFest runs 25–27 Sep at Cronulla Plaza — a free community festival. Easy first taste of Australia while you wait for check-in.', null, '/photos/d1_5.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '克羅努拉海灘 早餐', '9月25至27日 Cronulla Plaza 有社區節慶，免費入場。等入住之前輕輕鬆鬆感受下澳洲。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('ec4471b2-60ba-57cb-80b1-0ce1421d6671', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 1, '14:00', '18:30', 'Check in, then rest', '94b99b0c-9990-5355-9046-ad789308abf1', '🏨', 'stay', 'completed', 'booked', 'a68a7f41-94df-54e0-88bd-7b10617fd850', null, 114000, 35, 'Sydney East — Randwick / Kensington / Coogee', 'Do not skip the nap. Tomorrow is the longest day of the trip.', null, '/photos/d1_7.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '入住．休息', '一定要瞓返個覺。聽日係全程最長嘅一日。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('774c797b-5a0f-5194-b386-fb32204f9f76', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 1, '18:30', '20:00', 'Family dinner nearby', '3cac6b2d-1f19-5959-bfe5-de5a0bb8a139', '🍽️', 'food', 'completed', 'none', null, null, 14200, null, 'Near accommodation', 'Keep it short and local. Everyone has been awake since the flight.', null, '/photos/d1_8.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '就近家庭晚餐', '就近食，唔好搞太耐。由上機到而家大家都未真正休息過。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('588ace45-10c8-5946-9135-0e072c0b625f', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 2, '09:30', '11:00', 'Sydney Opera House — guided tour', '33c62630-8b8f-5e85-8985-ad4b06820475', '🎭', 'activity', 'completed', 'booked', '200da0c0-f284-503d-bf44-6ff649a9bcb5', null, 18000, null, 'Bennelong Point, Sydney NSW 2000', 'Book ahead, about one hour. Going inside is what makes this fresh even for those who have seen it many times.', null, '/photos/d2_1.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '悉尼歌劇院 導賞團', '要預先訂飛，約一個鐘。入到去內部參觀，就算之前嚟過幾次都會覺得新鮮。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('4cdc0f1b-0b05-5898-a2ff-517628e43b9e', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 2, '11:00', '12:30', 'Royal Botanic Garden → Mrs Macquarie''s Chair', '3395abdd-c6a5-5413-9e8c-b2688ad712c3', '🌿', 'activity', 'completed', 'none', null, null, null, null, 'Mrs Macquaries Rd, Sydney NSW 2000', 'Flat 2km walk through the gardens. The only spot where the Opera House and Harbour Bridge line up in one frame.', 'The photo: Stand at the point itself, not the car park. Late morning light comes from behind you.', '/photos/d2_2.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '皇家植物園 → 麥考利夫人石椅', '平路 2 公里，穿過植物園。全悉尼只有呢個位可以將歌劇院同海港大橋影入同一格。', '最靚影相位：要行到石椅個岬角，唔好停喺停車場。上晝尾嘅陽光喺你背後，最靚。');
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('9e90e5dc-1060-5a69-ac4b-e447ebb8a188', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 2, '12:30', '14:30', 'Lunch at The Rocks', 'adc8f1c3-1eae-5888-8b5f-70c8d97ae515', '🥪', 'food', 'completed', 'none', null, null, 9600, null, 'Playfair St, The Rocks NSW 2000', 'The Rocks Markets run all weekend — stalls, buskers, sandstone laneways under the bridge.', null, '/photos/d2_3.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '岩石區 午餐', '岩石區週末市集開足兩日 — 攤檔、街頭表演，砂岩窄巷就喺大橋腳下。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('6e762528-7ba3-5ffa-a084-8d748eb2de31', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 2, '14:30', '17:00', 'Ferry to Manly', '332af072-b22b-5726-995d-cefead18881c', '⛴️', 'transport', 'completed', 'none', null, null, 8640, null, 'Circular Quay Wharf 3, Alfred St, Sydney NSW 2000', 'Thirty minutes across the harbour and out past the Heads. Best-value harbour cruise anywhere. Manly Corso and the ocean beach at the far end.', null, '/photos/d2_4.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '渡輪往 曼利', '半個鐘橫渡海港，出到海口。全世界最抵坐嘅海港遊船。落船就係 Manly Corso 同海灘。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('4cc00b1c-fcee-5fee-8408-157b089f7806', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 2, '17:00', '19:00', 'Sunset ferry back', '4e334404-12d0-50ce-81a0-b33bc1209732', '🏄', 'transport', 'completed', 'none', null, null, null, null, 'Manly Wharf, E Esplanade, Manly NSW 2095', 'City skyline lighting up as you come in. Sunset is around 5:50pm — catch the 5:00 or 5:30 sailing.', null, '/photos/d2_5.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '日落 回程渡輪', '返程時市中心天際線啱啱著燈。日落約 5:50，搭 5:00 或 5:30 嗰班最好。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('8d35b64c-5961-56b5-821d-111b80986d92', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 2, '19:00', '20:30', 'Family dinner · harbour view', '1b6596fb-6cc7-53d8-ac8f-659a16508c12', '🦪', 'food', 'completed', 'booked', 'f5b147f1-722a-5d6d-81f3-0d8eb25ee1cd', null, 41200, null, 'To confirm — see checklist', 'Either a harbour-view restaurant at Circular Quay or Barangaroo, or a Chinese banquet round table if relatives are joining. Book now — Saturday night in Sydney fills a month ahead.', null, '/photos/d2_6.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '家庭晚宴', '可以揀環形碼頭或 Barangaroo 海景餐廳，如果親戚一齊就訂中菜圓枱。要即刻訂 — 悉尼星期六晚一個月前已經爆。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('dc3eacea-012a-5ba7-bb4d-bdaee800b535', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, '07:00', '08:00', 'Depart Sydney', '436a4ab4-5730-5d39-84cb-4205c3f2de53', '🚗', 'transport', 'completed', 'none', null, null, null, null, 'West on the M4 Motorway', 'Early start beats the coach tours to the lookouts. Roughly 1 hr 45 each way.', null, '/photos/d3_1.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '出發', '早出發可以趕喺旅遊巴之前到觀景台。單程約 1 小時 45 分。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('e9230e6f-1dff-54bd-95aa-f266067c724d', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, '09:00', '10:00', 'Echo Point — Three Sisters', '3a86ef0f-1fc5-51b8-bdf5-cb867ae33cf8', '⛰️', 'activity', 'completed', 'none', null, null, null, 60, 'Echo Point Rd, Katoomba NSW 2780', 'Free lookout, paid car park. Flat, railed and fully accessible. Get there before the buses arrive.', null, '/photos/d3_3.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '回音角 三姊妹峰', '觀景台免費，停車場收費。平路有欄杆，完全無障礙。要趕喺旅遊巴到之前。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('b90b86c8-5a28-55bc-a309-ac3a83b0cc9d', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, '10:00', '12:30', 'Scenic World', '5c5d72ad-3f2a-5978-8176-af27c38653f8', '🚡', 'activity', 'completed', 'booked', '2456ddb8-468f-5ba0-a862-e4ed0a2820b4', null, 23600, null, 'Cnr Violet St & Cliff Dr, Katoomba NSW 2780', 'Cableway, skyway and the steepest passenger railway in the world. Takes you deep into the valley with almost no walking. Book online — Sunday queues are real.', null, '/photos/d3_4.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '景觀世界', '纜車、高空吊車同全球最斜嘅登山railway。可以落到谷底，幾乎唔使行路。網上訂飛 — 星期日真係要排隊。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('772e888d-30de-59db-b243-c7a4b01ba006', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, '12:30', '14:30', 'Lunch at Leura', 'db1a5301-7ca1-515d-bd5c-f8bd0b28ddbf', '🍫', 'food', 'completed', 'none', null, null, 7800, null, 'Leura Mall, Leura NSW 2780', 'Pretty village main street, plenty of cafes. Josophan''s for chocolate.', null, '/photos/d3_5.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '露拉鎮 午餐', '好靚嘅小鎮大街，好多咖啡店。Josophan''s 嘅朱古力值得買。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('b8775c8a-b282-56a6-b072-6059c96297cc', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, '14:30', '16:30', 'Wentworth Falls — Princes Rock lookout', '68d82981-d787-5c08-8884-871cb4ff31eb', '💦', 'activity', 'completed', 'none', null, null, null, null, 'Falls Rd, Wentworth Falls NSW 2782', 'Short walk, big reward. Skip the long staircase descent to the base of the falls.', null, '/photos/d3_6.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '溫特沃斯瀑布 王子岩觀景台', '行一陣就到，景觀非常好。落瀑布底嗰條長樓梯就唔好行喇。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('9cebeb06-69fa-52f3-976f-0eb6b79d358f', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, '16:30', '18:00', 'Cahill''s Lookout', 'da6b9974-f8ec-5855-83b7-394b0e0f35c2', '🌄', 'activity', 'completed', 'none', null, null, null, null, 'Cliff Dr, Katoomba NSW 2780', 'Same valley as Echo Point, a fraction of the crowd, and the best light of the day.', null, '/photos/d3_7.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '卡希爾觀景台', '同回音角望同一個山谷，但人少好多，而且係全日最靚嘅光線。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('c9c8c173-aa80-5aa5-a761-2a0fb3902b5d', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 3, '19:00', '20:30', 'Dinner near the hotel', '3cac6b2d-1f19-5959-bfe5-de5a0bb8a139', '🍽️', 'food', 'completed', 'none', null, null, 12400, 60, 'Sydney East', 'Something simple. It has been a long day in the car.', null, '/photos/d3_9.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '回程晚餐', '食簡單啲。今日坐咗好耐車。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('d1115344-b573-58cd-bd9b-893939470b9d', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 4, '09:00', '09:30', 'Bondi Beach', '9ae6927e-a6cc-5dc2-bb9f-678f26fdf82f', '🏖️', 'activity', 'confirmed', 'none', null, null, null, null, 'Queen Elizabeth Dr, Bondi Beach NSW 2026', 'Paid parking along the beachfront. Cold for swimming, perfect for walking.', null, '/photos/d4_0.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '邦迪海灘', '沿海灘有收費泊車位。仲凍唔適合游水，但好適合散步。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('5602aad3-56e0-5c81-9cda-7fe0e67307c9', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 4, '09:30', '12:00', 'Bondi to Bronte clifftop walk', '5a32e369-452f-541d-9d87-bc331ac15dd5', '🚶', 'activity', 'confirmed', 'none', null, null, null, null, 'Bondi to Bronte Coastal Walk, Bondi Beach NSW 2026', '2.5km, paved, gentle steps, ocean on your left the whole way. Whales are visible from the cliffs this time of year. Extend to Coogee (6km) only if everyone is fresh.', null, '/photos/d4_1.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '邦迪至布朗特 海崖步道', '2.5 公里石屎路，梯級唔斜，全程左手邊都係大海。呢個季節喺崖邊望得到鯨魚。如果大家仲有力先行埋去 Coogee（共 6 公里）。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('d93f8f6b-a345-5592-ad7d-8207230d31a5', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 4, '12:00', '14:30', 'Lunch at Bronte or Bondi', '02c9174a-295e-52e5-8ec0-8fd3bd1e2776', '🐟', 'food', 'confirmed', 'none', null, null, 11200, null, 'Bronte Rd, Bronte NSW 2024', 'Bus back, or walk the same path in reverse.', null, '/photos/d4_2.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '午餐', '可以搭巴士返，或者原路行返轉頭。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('f63b14b8-0912-5996-9333-a18dc3d83257', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 4, '14:30', '18:30', 'UNSW Kensington campus', 'ddb85519-968c-51cc-98c7-7e5730177035', '🎓', 'activity', 'confirmed', 'none', null, null, null, null, 'High St, Kensington NSW 2052', 'Go on a weekday when the campus is alive. Forty minutes is plenty — the library lawn, the main walkway, a coffee.', null, '/photos/d4_3.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '新南威爾斯大學 肯辛頓校園', '平日去，校園先有生氣。四十分鐘已經足夠 — 圖書館草地、主步道，飲杯咖啡。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('f0d67687-eac7-545b-b6d0-1d425daab853', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 4, '18:30', '20:00', 'Dinner with relatives', '624bac38-84e7-509a-806e-a365ad0d6fc6', '👨‍👩‍👧‍👦', 'food', 'voting', 'none', null, '3002fb93-5926-53e7-a736-be78e69a7f15', 18000, null, 'To confirm — see checklist', 'Ask them now which evenings they can do. Their availability decides the rest of the week.', null, '/photos/d4_4.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '親戚晚餐', '即刻問下佢哋邊晚得閒。佢哋嘅時間會決定成個星期點編排。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('d1fc6f7a-38cf-511e-87f4-6ba69db13886', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 5, '08:30', '09:00', 'Depart Sydney', 'c5a0df69-ec7e-5fb7-85ce-8cf19dbd6140', '🚗', 'transport', 'confirmed', 'none', null, null, null, null, 'South via the Princes Motorway', 'Beat the southbound morning peak.', null, '/photos/d5_1.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '出發', '避開朝早南行嘅塞車時段。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('dbd29feb-4ec1-5623-b297-b21d05958e0e', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 5, '09:45', '10:30', 'Sea Cliff Bridge', '567e0885-a4cd-5851-8ca1-277dae8e94da', '🌉', 'activity', 'confirmed', 'none', null, null, null, 60, 'Lawrence Hargrave Dr, Coalcliff NSW 2508', '665 metres of road cantilevered out over the open ocean. Park at the northern end and walk the pedestrian side. Bald Hill lookout is five minutes further north.', 'Today''s highlight: The best drive within two hours of Sydney, and new even for repeat visitors.', '/photos/d5_3.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '海崖大橋', '665 米長嘅懸臂公路，直接架喺大海之上。喺北面泊車，行行人路過橋。再北五分鐘就係 Bald Hill 觀景台。', '今日重點：悉尼兩小時車程內最靚嘅一段路，就算嚟過幾次都未必見過。');
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('a948df16-8b6a-5dc4-bd53-ce0f9edb5d89', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 5, '11:30', '12:30', 'Kiama Blowhole', 'a5bc7146-3fa3-5565-b401-b887353451d2', '🌊', 'activity', 'confirmed', 'none', null, null, null, 60, 'Blowhole Point Rd, Kiama NSW 2533', 'Best on a southeasterly swell. Lighthouse and rock platform right beside it, all flat ground.', null, '/photos/d5_5.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '基亞瑪 噴水洞', '東南風有浪嗰陣最壯觀。旁邊就係燈塔同岩石平台，全部平路。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('82389486-d128-5e43-a44d-c0c10127e987', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 5, '12:30', '14:00', 'Lunch — Kiama Harbour', '79b9b351-900b-5e4d-ad85-560682a59805', '🍟', 'food', 'confirmed', 'none', null, null, 7600, null, 'Blowhole Point Rd, Kiama NSW 2533', 'Fish and chips by the water.', null, '/photos/d5_6.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '基亞瑪碼頭 午餐', '喺海邊食炸魚薯條。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('0853e228-ec5f-5e58-b24b-059b6a2262a6', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 5, '15:00', '17:00', 'Check in — Huskisson', '54543fe7-5c60-5291-9df0-2b26fcf55017', '🏡', 'stay', 'confirmed', 'needed', null, null, 52000, 60, 'Owen St, Huskisson NSW 2540', 'Small seaside town. Everything is walkable from the main street.', null, '/photos/d5_8.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '入住 哈斯基森', '細細個海邊小鎮。由大街行得晒去所有地方。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('50012488-a189-56ab-8380-efade6591dea', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 5, '17:00', '18:00', 'Hyams Beach — sunset', '4f003a30-84b3-59eb-9765-42f5dd471ccf', '🏝️', 'activity', 'confirmed', 'none', null, null, null, null, 'Cyril Ave, Hyams Beach NSW 2540', 'Some of the whitest sand in the world — it squeaks underfoot. Parking is limited, so go early or park in the village and walk in.', null, '/photos/d5_9.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '海姆斯海灘 日落', '沙白到全球有名，行落去會響。泊車位好少，早啲去或者泊喺村入面行入沙灘。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('70a37f97-8230-5a7d-8ae3-88924ae4171b', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 6, '09:00', '09:30', 'Booderee National Park', '71d4c186-fd6d-5ad2-8914-f3f36de4fbb3', '🌳', 'activity', 'confirmed', 'none', null, null, 1700, null, 'Jervis Bay Rd, Jervis Bay JBT 2540', 'Vehicle entry fee at the gate, valid 48 hours. Card accepted.', null, '/photos/d6_0.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '布德里國家公園', '入口收車輛入場費，48 小時內有效。可用信用卡。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('f746437b-c755-5e1c-ae88-1c6f86b98f14', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 6, '09:30', '11:00', 'Murrays Beach', 'ee3e83fa-6d68-5814-b0b6-42ed04fc654c', '🏝️', 'activity', 'confirmed', 'none', null, null, null, null, 'Murrays Beach Rd, Booderee National Park', 'Sheltered, turquoise water, short walk from the car park. The prettiest beach in the park.', null, '/photos/d6_1.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '默里斯海灘', '避風、水色碧綠，由停車場行少少就到。全公園最靚嘅海灘。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('7b227d3b-de0b-5ea8-bdb7-9f62412cc47b', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 6, '11:00', '13:30', 'Cape St George Lighthouse ruins', '4b942ed1-f247-5702-bf35-b8066ed79e57', '🗼', 'activity', 'confirmed', 'none', null, null, null, null, 'Stony Creek Rd, Booderee National Park', 'Clifftop ruins and one of the best land-based whale watching headlands on the east coast. Bring binoculars.', null, '/photos/d6_2.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '聖佐治角 燈塔遺址', '崖頂遺址，亦係東岸最好嘅陸上觀鯨點之一。記得帶望遠鏡。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('835eed2a-bdd2-5901-8453-d8245104faa0', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 6, '13:30', '16:30', 'Dolphin & whale cruise', 'a6f6c699-3943-5e0e-805f-eccb25302bb6', '🐬', 'activity', 'confirmed', 'needed', null, null, 34000, null, 'Dolphin Watch Cruises, 50 Owen St, Huskisson NSW 2540', 'Sheltered bay water, far gentler than the open-ocean Sydney cruises. Resident bottlenose dolphins year-round, humpbacks with calves passing through in late September.', 'If anyone gets seasick: This is the cruise to do, not the Sydney one. Jervis Bay is protected water.', '/photos/d6_3.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '觀豚觀鯨 遊船', '灣內風平浪靜，比悉尼出海嗰啲平穩好多。全年都有樽鼻海豚，9月底仲有母鯨帶住鯨仔經過。', '如果有人暈船：就揀呢隻船，唔好喺悉尼出海。傑維斯灣係內灣，好平穩。');
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('a552e45f-1440-5bfa-933d-ba9cc26051ec', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 6, '16:30', '18:30', 'White Sands Walk', 'cc88aeb6-4ace-59c4-bb99-d1919d319c05', '🚶', 'activity', 'confirmed', 'none', null, null, null, null, 'Greenfield Beach, Vincentia NSW 2540', '3km easy coastal path linking the beaches. Turn back whenever you like.', null, '/photos/d6_4.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '白沙步道', '3 公里易行海岸路，連接幾個海灘。行到邊算邊，隨時折返。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('d1b2d67e-680a-5568-86c7-ad5112853007', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 6, '18:30', '20:00', 'Dinner in Huskisson', 'e69ae7f3-5d73-57b8-bf85-e763a20d95b6', '🍽️', 'food', 'confirmed', 'none', null, null, 16000, null, 'Owen St, Huskisson NSW 2540', 'Walk from the accommodation. Book if it looks busy.', null, '/photos/d6_5.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '哈斯基森 晚餐', '由住宿行過去就得。如果多人記得訂枱。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('4ede46c0-f9e8-59a5-a4ac-63a5e5c50be0', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 7, '09:00', '09:30', 'Depart Huskisson', '54543fe7-5c60-5291-9df0-2b26fcf55017', '🏡', 'transport', 'confirmed', 'none', null, null, null, null, 'North-west via Kangaroo Valley', 'Inland route home instead of retracing the coast.', null, '/photos/d7_0.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '出發', '行內陸路返，唔使原路沿海岸行返轉頭。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('ddeb84da-8971-5c19-9021-2a564aaa27db', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 7, '09:45', '10:50', 'Hampden Bridge, Kangaroo Valley', 'd744d4c3-72a9-5574-87bb-fff93e3d6178', '🌉', 'activity', 'confirmed', 'none', null, null, null, 45, 'Moss Vale Rd, Kangaroo Valley NSW 2577', 'Sandstone-turreted suspension bridge from 1898, spanning a green river valley. Coffee in the village.', null, '/photos/d7_2.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '袋鼠谷 漢普頓吊橋', '1898 年建成、有砂岩塔樓嘅吊橋，橫跨翠綠河谷。可以喺村入面飲返杯咖啡。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('cd0a651a-abf9-5140-b83f-da927d7360be', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 7, '11:30', '13:00', 'Fitzroy Falls', '7b1e69b5-a281-5713-9d9f-20ae433757c3', '💦', 'activity', 'confirmed', 'none', null, null, null, 40, '1301 Nowra Rd, Fitzroy Falls NSW 2577', 'An 81-metre drop. Ten-minute flat walk from the visitor centre to the main lookout. Cafe and toilets on site.', 'This replaces Bowral: You keep the best Southern Highlands scenery without needing an overnight stop.', '/photos/d7_4.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '菲茨羅伊瀑布', '落差 81 米。由遊客中心行平路十分鐘就到主觀景台。有咖啡店同洗手間。', '取代原本嘅 Bowral：唔使過夜都睇到南部高地最靚嘅風景。');
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('e6983a0c-222a-5423-abf6-fd572769324e', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 7, '13:00', '15:00', 'Lunch — Berrima', 'ebf6885c-ecdb-5a62-90ee-55129d10802b', '🥧', 'food', 'confirmed', 'none', null, null, 8800, null, 'Berrima NSW 2577', 'Historic sandstone village, 1830s buildings, easy parking. Robertson has the pie shop if you prefer.', null, '/photos/d7_5.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '貝里瑪 午餐', '歷史砂岩小鎮，1830 年代建築，泊車容易。想食批嘅話可以去 Robertson。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('32fcf7f6-c66c-5518-b3eb-39fcc3aadc88', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 7, '16:00', '18:30', 'Back at the Sydney hotel', '94b99b0c-9990-5355-9046-ad789308abf1', '🏨', 'stay', 'confirmed', 'none', null, null, null, 60, 'Sydney East', 'Unpack and rest.', null, '/photos/d7_7.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '返到悉尼住宿', '執返好行李，唞返陣。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('bdd10aa2-d299-54e4-8e95-f6e8fe404aa5', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 7, '18:30', '20:00', 'Quiet dinner', '3cac6b2d-1f19-5959-bfe5-de5a0bb8a139', '🍽️', 'food', 'confirmed', 'none', null, null, 15000, null, 'To confirm', 'A driving day. Do not over-book tonight — keep it local.', null, '/photos/d7_8.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '簡單晚餐', '今日揸咗成日車。今晚唔好安排太多，就近食就得。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('75395a22-e8d7-5595-858b-0b7a79e16ab4', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 8, '10:00', '16:00', 'Free day — group decision', null, '🗳️', 'free', 'voting', 'none', null, '01b0e742-0a2c-52be-9522-537f32200493', null, null, null, 'Deliberately unplanned. Pick one or two of the options, not all four.', null, '/photos/banner8.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '自由日 — 小組決定', '故意留白。喺選項入面揀一至兩樣就夠，唔好四樣都做。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('87d6aca3-4f5b-5e44-851c-ed156f487e92', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 8, '18:30', '20:30', 'Family dinner', null, '🦪', 'food', 'voting', 'none', null, '53bc2688-9284-5e39-9c6c-b710165eb5e5', 34000, null, 'To confirm — see checklist', 'Start of the long weekend, so relatives should be free. Book ahead — Friday night before a public holiday is busy.', null, '/photos/d8_5.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '家庭晚餐', '長週末開始，親戚應該得閒。要預先訂枱 — 公眾假期前嘅星期五晚好多人。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('77f900e9-9250-5eb6-93a9-672743c703ac', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 9, '07:15', '09:00', 'Sydney Fish Market — optional', '62d49d5a-f069-5b29-a4c3-80a51c4a8d24', '🐟', 'activity', 'confirmed', 'none', null, null, 10000, null, '1 Bridge Rd, Glebe NSW 2037', 'Only if everything is packed. The new $836m market on Blackwattle Bay opened January 2026 — wave-shaped roof, 40+ traders, live auctions behind glass. Leave by 08:30, no later.', 'New location: Not the old Pyrmont site. Set the GPS to 1 Bridge Road, Glebe.', '/photos/d9_1.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '悉尼魚市場（可選）', '執好晒行李先好去。Blackwattle Bay 全新市場 2026年1月開幕，造價 8.36 億，波浪型天幕、40 多個商戶、玻璃後面睇得到魚市拍賣。08:30 前一定要走。', '新地址：唔係舊嗰個 Pyrmont 地址。GPS 要輸入 1 Bridge Road, Glebe。');
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('4c3ff524-6d1c-5b16-a980-f05e57db0802', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 9, '09:00', '09:30', 'Check out', '94b99b0c-9990-5355-9046-ad789308abf1', '🏨', 'stay', 'confirmed', 'booked', 'a68a7f41-94df-54e0-88bd-7b10617fd850', null, null, null, 'Sydney East', 'Check drawers, safes, chargers, passports.', null, '/photos/d9_2.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '退房', '檢查抽屜、夾萬、充電器、護照。', null);
insert into itinerary_items (id, trip_id, day, start_time, end_time, title, place_id, emoji, category, status, booking, booking_id, decision_id, cost_minor, travel_min, address, note, flag, photo_url, participant_ids, created_by, title_zh, note_zh, flag_zh) values ('25787c15-a0d0-5cd9-92b9-d08a4edc449f', 'e7e3d9aa-c06b-5205-a23a-8a9b382ecbf7', 9, '09:45', '10:30', 'Refuel near the airport', '726e172d-5b93-5dd8-8f52-8831ea52db17', '⛽', 'transport', 'confirmed', 'none', null, null, null, 25, 'O''Riordan St, Mascot NSW 2020', 'The car must come back full or they charge a premium refuelling rate. Allow 30 minutes and keep the receipt.', null, '/photos/d9_4.jpg', array['2ebd5e74-6f79-5ea1-b8a0-3f28051311ca','05e4171b-299e-5ad3-8bfd-ef9b0edd42cc','14a701e0-996b-5f0b-8cde-d1914aec7a67','7e49bd3b-9097-5d1d-805e-25326190b666']::uuid[], '2ebd5e74-6f79-5ea1-b8a0-3f28051311ca', '機場附近入油', '還車一定要滿缸，否則會收高價入油費。預 30 分鐘，收據要留返。', null);
